    ["ocupación",r.ocupacion,"estructura PIB sectorial del dpto (DANE) + dossier regional"],
    ["educación",r.educacion||"—","CNPV 2018 cuadro 17PD (nivel alcanzado)"],
    ["salud",r.regimen_salud,"cobertura MinSalud del dpto (datos.gov.co)"],
